package org.sleepwell.app;
import android.content.*;import java.util.*;
/** Explicit self-report only, separate from records, recorded rhythm, and portable backups. */
final class HabitualTimingSettings {
 interface Factory{SharedPreferences open(Context c);}static Factory factory=c->c.getSharedPreferences("sleepwell-habitual-timing",0);
 static HabitualTiming read(SharedPreferences p){Map<String,?> values=p.getAll();HabitualTiming t=new HabitualTiming();t.workOnset=integer(values,"workOnset",-1);t.workEnd=integer(values,"workEnd",-1);t.freeOnset=integer(values,"freeOnset",-1);t.freeEnd=integer(values,"freeEnd",-1);t.workdays=integer(values,"workdays",-1);t.regular=integer(values,"regular",0);t.freeAlarm=integer(values,"freeAlarm",0);t.unrestricted=integer(values,"unrestricted",0);Object zone=values.get("zone"),revision=values.get("revision");if(zone!=null&&!(zone instanceof String)||revision!=null&&!(revision instanceof Long))throw new IllegalStateException("Saved timing inputs need attention. Existing data was kept.");if(zone!=null)t.zone=(String)zone;if(revision!=null)t.revision=(Long)revision;t.validate();return t;}
 private static int integer(Map<String,?> values,String key,int fallback){Object value=values.get(key);if(value==null)return fallback;if(!(value instanceof Integer))throw new IllegalStateException("Saved timing inputs need attention. Existing data was kept.");return (Integer)value;}
 static synchronized void save(SharedPreferences p,HabitualTiming value,long expected){value.validate();HabitualTiming current=read(p);if(current.revision!=expected)throw new IllegalStateException("Your timing inputs changed elsewhere. Reload before saving.");if(expected==Long.MAX_VALUE)throw new IllegalStateException("Saved timing revision needs attention.");long revision=Math.max(System.currentTimeMillis(),expected+1);if(!p.edit().putInt("workOnset",value.workOnset).putInt("workEnd",value.workEnd).putInt("freeOnset",value.freeOnset).putInt("freeEnd",value.freeEnd).putInt("workdays",value.workdays).putInt("regular",value.regular).putInt("freeAlarm",value.freeAlarm).putInt("unrestricted",value.unrestricted).putString("zone",value.zone).putLong("revision",revision).commit())throw new IllegalStateException("Timing inputs could not be saved.");value.revision=revision;}
 private HabitualTimingSettings(){}
}
